// store/index.js
import Vue from 'vue'
import Vuex from 'vuex'
import { chromeStorage } from '@/utils/storage'

Vue.use(Vuex)

export default new Vuex.Store({
  state: {
    savedJobs: [],
    templates: [],
    currentJob: null,
    settings: {
      autoDetect: true,
      notifications: true
    }
  },

  mutations: {
    SET_JOBS(state, jobs) {
      state.savedJobs = jobs
    },
    ADD_JOB(state, job) {
      state.savedJobs.unshift({
        ...job,
        id: Date.now(),
        savedAt: new Date().toISOString()
      })
    },
    SET_CURRENT_JOB(state, job) {
      state.currentJob = job
    }
  },

  actions: {
    async loadJobs({ commit }) {
      const jobs = await chromeStorage.get('savedJobs') || []
      commit('SET_JOBS', jobs)
    },

    async saveJob({ commit, state }) {
      commit('ADD_JOB', state.currentJob)
      await chromeStorage.set('savedJobs', state.savedJobs)
    }
  }
})

