// content/jobExtractor.js
const siteSelectors = {
  'linkedin.com': {
    title: '.job-details-jobs-unified-top-card__job-title',
    company: '.job-details-jobs-unified-top-card__company-name',
    location: '.job-details-jobs-unified-top-card__bullet',
    description: '.jobs-description__content'
  },
  'indeed.com': {
    title: '.jobsearch-JobInfoHeader-title',
    company: '[data-company-name="true"]',
    location: '[data-testid="job-location"]',
    description: '#jobDescriptionText'
  },
  'glassdoor.com': {
    title: '[data-test="job-title"]',
    company: '[data-test="employer-name"]',
    location: '[data-test="location"]',
    description: '.desc'
  }
}

export function extractJobData() {
  const hostname = window.location.hostname.replace('www.', '')
  const selectors = Object.entries(siteSelectors)
    .find(([site]) => hostname.includes(site))?.[1]

  if (!selectors) return null

  return {
    title: document.querySelector(selectors.title)?.textContent?.trim(),
    company: document.querySelector(selectors.company)?.textContent?.trim(),
    location: document.querySelector(selectors.location)?.textContent?.trim(),
    description: document.querySelector(selectors.description)?.innerHTML,
    url: window.location.href,
    source: hostname
  }
}

// background/index.js
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  switch (request.type) {
    case 'SAVE_JOB':
      handleSaveJob(request.job).then(sendResponse)
      return true

    case 'GET_TEMPLATES':
      chrome.storage.local.get('templates', (result) => {
        sendResponse(result.templates || defaultTemplates)
      })
      return true

    case 'APPLY_TEMPLATE':
      const filled = applyTemplateVariables(
        request.template, 
        request.variables
      )
      sendResponse({ text: filled })
      return true
  }
})

function applyTemplateVariables(template, variables) {
  return template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
    return variables[key] || match
  })
}

const defaultTemplates = [
  {
    name: 'Cover Letter - General',
    content: 'Dear Hiring Manager,\n\nI am excited to apply for the {{position}} role at {{company}}...'
  },
  {
    name: 'Follow-up Email',
    content: 'Hi {{recruiterName}},\n\nI wanted to follow up on my application for {{position}}...'
  }
]

